result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/app/main.py", "content": """"Sequence database mini-service.

FastAPI + SQLite (WAL mode). Each request opens its own connection with a
generous busy_timeout, so concurrent writers simply queue instead of failing.
"""
import os
import re
import sqlite3
import uuid
from contextlib import contextmanager
from typing import Optional

from fastapi import FastAPI, HTTPException, Query
from pydantic import BaseModel, field_validator

DB_PATH = os.environ.get("SEQDB_PATH", "sequences.db")

SEQ_RE = re.compile(r"^[ACGTN]+$")
KMER_RE = re.compile(r"^[ACGT]+$")

_COMP_TABLE = str.maketrans("ACGTNacgtn", "TGCANtgcan")


def revcomp(seq: str) -> str:
    """Reverse complement; N complements to N."""
    return seq.translate(_COMP_TABLE)[::-1]


def gc_fraction(seq: str) -> float:
    """Fraction of bases that are G or C. Empty sequence -> 0.0."""
    if not seq:
        return 0.0
    seq = seq.upper()
    return (seq.count("G") + seq.count("C")) / len(seq)


@contextmanager
def get_db():
    conn = sqlite3.connect(DB_PATH, timeout=30.0)
    try:
        conn.execute("PRAGMA journal_mode=WAL")
        conn.execute("PRAGMA synchronous=NORMAL")
        conn.execute("PRAGMA busy_timeout=30000")
        conn.row_factory = sqlite3.Row
        yield conn
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def init_db() -> None:
    with get_db() as db:
        db.execute(
            """
            CREATE TABLE IF NOT EXISTS sequences (
                id     TEXT PRIMARY KEY,
                name   TEXT NOT NULL,
                seq    TEXT NOT NULL,
                length INTEGER NOT NULL,
                gc     REAL NOT NULL
            )
            """
        )


app = FastAPI(title="Sequence DB", version="1.0.0")


@app.on_event("startup")
def _startup() -> None:
    init_db()


# ---------------------------------------------------------------- models


class SequenceIn(BaseModel):
    id: Optional[str] = None
    name: str
    seq: str

    @field_validator("name")
    @classmethod
    def _name_not_blank(cls, v: str) -> str:
        if not v.strip():
            raise ValueError("name must not be blank")
        return v

    @field_validator("seq")
    @classmethod
    def _valid_bases(cls, v: str) -> str:
        v = v.upper()
        if not SEQ_RE.match(v):
            raise ValueError("seq must contain only A, C, G, T or N")
        return v


class SequenceOut(BaseModel):
    id: str
    name: str
    seq: str
    length: int
    gc: float


class KmerIn(BaseModel):
    kmer: str

    @field_validator("kmer")
    @classmethod
    def _valid_kmer(cls, v: str) -> str:
        v = v.upper()
        if not KMER_RE.match(v):
            raise ValueError("kmer must contain only A, C, G or T (no N)")
        return v


class Match(BaseModel):
    offset: int
    strand: str  # '+' or '-'


class SearchHit(BaseModel):
    id: str
    name: str
    length: int
    gc: float
    matches: list[Match]


class SearchOut(BaseModel):
    kmer: str
    query_revcomp: str
    results: list[SearchHit]


# ------------------------------------------------------------- endpoints


@app.get("/health")
def health() -> dict:
    return {"status": "ok"}


@app.post("/sequences", response_model=SequenceOut, status_code=201)
def create_sequence(payload: SequenceIn) -> SequenceOut:
    seq_id = payload.id or uuid.uuid4().hex[:12]
    with get_db() as db:
        if db.execute(
            "SELECT 1 FROM sequences WHERE id = ?", (seq_id,)
        ).fetchone():
            raise HTTPException(status_code=409, detail=f"id '{seq_id}' already exists")
        db.execute(
            "INSERT INTO sequences (id, name, seq, length, gc) VALUES (?, ?, ?, ?, ?)",
            (seq_id, payload.name, payload.seq, len(payload.seq), gc_fraction(payload.seq)),
        )
    return SequenceOut(
        id=seq_id,
        name=payload.name,
        seq=payload.seq,
        length=len(payload.seq),
        gc=gc_fraction(payload.seq),
    )


@app.get("/sequences", response_model=list[SequenceOut])
def list_sequences(
    min_gc: Optional[float] = Query(None, ge=0.0, le=1.0),
    max_len: Optional[int] = Query(None, ge=1),
) -> list[SequenceOut]:
    clauses, params = [], []
    if min_gc is not None:
        clauses.append("gc >= ?")
        params.append(min_gc)
    if max_len is not None:
        clauses.append("length <= ?")
        params.append(max_len)
    where = f"WHERE {' AND '.join(clauses)}" if clauses else ""
    with get_db() as db:
        rows = db.execute(
            f"SELECT id, name, seq, length, gc FROM sequences {where} ORDER BY rowid", params
        ).fetchall()
    return [SequenceOut(**dict(r)) for r in rows]


@app.get("/sequences/{seq_id}/revcomp", response_model=dict)
def reverse_complement(seq_id: str) -> dict:
    with get_db() as db:
        row = db.execute(
            "SELECT id, seq FROM sequences WHERE id = ?", (seq_id,)
        ).fetchone()
    if row is None:
        raise HTTPException(status_code=404, detail=f"sequence '{seq_id}' not found")
    rc = revcomp(row["seq"])
    return {"id": row["id"], "revcomp": rc, "length": len(rc), "gc": gc_fraction(rc)}


def _find_all(seq: str, kmer: str) -> list[int]:
    """All (including overlapping) occurrence offsets of kmer in seq."""
    offsets, pos = [], 0
    while (pos := seq.find(kmer, pos)) != -1:
        offsets.append(pos)
        pos += 1
    return offsets


@app.post("/search", response_model=SearchOut)
def search(payload: KmerIn) -> SearchOut:
    kmer = payload.kmer
    rc = revcomp(kmer)
    hits: list[SearchHit] = []
    with get_db() as db:
        rows = db.execute("SELECT id, name, seq, length, gc FROM sequences").fetchall()
    for r in rows:
        matches = [Match(offset=o, strand="+") for o in _find_all(r["seq"], kmer)]
        matches += [Match(offset=o, strand="-") for o in _find_all(r["seq"], rc)]
        if matches:
            matches.sort(key=lambda m: m.offset)
            hits.append(
                SearchHit(id=r["id"], name=r["name"], length=r["length"], gc=r["gc"], matches=matches)
            )
    return SearchOut(kmer=kmer, query_revcomp=rc, results=hits)
